B2BRolePrivManagement = {
    init: async function (app, container, role) {
        app = app || session.app;
        container = $(
            container ||
            '.component[name=B2BRolePrivManagement]'
        );

        if (!role) {
            return;
        }

        var privs = (
            await api.get("B2B/B2BPrivilege")
        ).value;

        var assignedPrivs = new Set(
            (role.Privs || "")
                .split(",")
                .filter(Boolean)
        );

        privs.forEach(function (privilege) {
            privilege.Has = assignedPrivs.has(privilege.Id);
        });

        var rolePrivGrid = new GridWidget(
            container,
            { data: privs }
        );

        rolePrivGrid.columns = [
            {
                field: "Has",
                title: " ",
                template: function (dataItem) {
                    return (
                        "<input type='checkbox' " +
                        "class='k-select-checkbox k-checkbox " +
                        "k-checkbox-md k-rounded-md chkbx' " +
                        (dataItem.Has ? "checked='checked' " : "") +
                        "/>"
                    );
                },
                width: 40
            },
            {
                field: "Type",
                title: "[resource_displayname[Type]]"
            },
            {
                field: "Operation",
                title: "[resource_displayname[Operation]]"
            },
            {
                field: "Description",
                title:
                    "[resource_displayname[PrivExplanation]]"
            }
        ];

        rolePrivGrid.groupable = false;
        rolePrivGrid.editable = false;
        rolePrivGrid.pageable = false;
        rolePrivGrid.filterable = false;
        rolePrivGrid.sortable = false;

        rolePrivGrid.dataBound = function () {
            B2BRolePrivManagement.onGridDataBound(
                role,
                rolePrivGrid
            );
        };

        await rolePrivGrid.init();

        rolePrivGrid.kendoObject.dataSource.group({
            field: "Type"
        });
    },

    onGridDataBound: function (role, rolePrivGrid) {
        $("input[type=checkbox]", rolePrivGrid.gridElement)
            .off("click.b2bRolePriv")
            .on("click.b2bRolePriv", function (e) {
                B2BRolePrivManagement.onPrivClick(
                    e,
                    role,
                    rolePrivGrid
                );
            });
    },

    onPrivClick: async function (
        e,
        role,
        rolePrivGrid
    ) {
        var dataItem =
            rolePrivGrid.kendoObject.dataItem(
                $(e.currentTarget).closest("tr")
            );

        if (!dataItem) {
            return;
        }

        dataItem.set(
            "Has",
            e.currentTarget.checked
        );

        role.Privs = rolePrivGrid.kendoObject.dataSource
            .data()
            .filter(function (privilege) {
                return privilege.Has;
            })
            .map(function (privilege) {
                return privilege.Id;
            })
            .join(",");

        await role.save()
            .then(function () {
                notification.success(
                    "[resource_displayname[rolesaved]]"
                );
            })
            .catch(function (err) {
                error(err);
            });
    }
};
